import { create, StateCreator } from 'zustand'
import { persist } from 'zustand/middleware'

interface globalState {
  binStepConfig: any[] | undefined
  setBinStepConfig: (value: any[] | undefined) => void
}

const store: StateCreator<globalState> = (set, get) => ({
  binStepConfig: undefined,
  setBinStepConfig: (value: any[] | undefined) => {
    set(() => ({
      binStepConfig: value
    }))
  }
})

const useBinStepConfigStore = create(
  persist(store, {
    name: 'bin-step-config',
    partialize: state => {
      const { binStepConfig } = state
      return { binStepConfig }
    }
  })
)
export default useBinStepConfigStore
